#requires -Version 5.1
# StockFlow roles / access / assigned trading points installer.
# Built from the ZIP provided in this chat + installed StockFlow Refresh.
# No database updates, no data deletion, no password changes.
$ErrorActionPreference = 'Stop'
$projectRoot = $PSScriptRoot
if (-not (Test-Path -LiteralPath (Join-Path $projectRoot 'TradingManagementSystem.slnx') -PathType Leaf)) {
    throw 'Place this script next to TradingManagementSystem.slnx in the project root.'
}
$web = Join-Path $projectRoot 'TradingManagementSystem.Web'
if (-not (Test-Path -LiteralPath (Join-Path $web 'Controllers\ProfileController.cs') -PathType Leaf) -or
    -not (Test-Path -LiteralPath (Join-Path $web 'Views\Profile\Index.cshtml') -PathType Leaf)) {
    throw 'The StockFlow profile/design upgrade is not installed. Install it first; nothing was modified.'
}
$layout = Get-Content -LiteralPath (Join-Path $web 'Views\Shared\_Layout.cshtml') -Raw
if (-not $layout.Contains('stockflow-refresh.css')) {
    throw 'Current layout differs from expected refreshed StockFlow version. Nothing was modified.'
}
