    'TradingManagementSystem.Web/Program.cs'
    'TradingManagementSystem.Web/Views/Catalog/Products.cshtml'
    'TradingManagementSystem.Web/Views/Catalog/Purchases.cshtml'
    'TradingManagementSystem.Web/Views/Catalog/Receipts.cshtml'
    'TradingManagementSystem.Web/Views/Catalog/Sales.cshtml'
    'TradingManagementSystem.Web/Views/Catalog/Suppliers.cshtml'
    'TradingManagementSystem.Web/Views/Employees/Create.cshtml'
    'TradingManagementSystem.Web/Views/Employees/Edit.cshtml'
    'TradingManagementSystem.Web/Views/Employees/Index.cshtml'
    'TradingManagementSystem.Web/Views/Shared/_Layout.cshtml'
)
$temp = Join-Path ([IO.Path]::GetTempPath()) ('StockFlow-Roles-Install-' + [Guid]::NewGuid().ToString('N'))
$extract = Join-Path $temp 'payload'
$zipFile = Join-Path $temp 'code.zip'
$backup = Join-Path ([IO.Path]::GetTempPath()) ('StockFlow-Roles-Backup-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
New-Item -ItemType Directory -Path $temp -Force | Out-Null
New-Item -ItemType Directory -Path $backup -Force | Out-Null
try {
    [IO.File]::WriteAllBytes($zipFile,[Convert]::FromBase64String(($encoded -replace '\s','')))
    Expand-Archive -LiteralPath $zipFile -DestinationPath $extract -Force
    foreach ($entry in $files) {
        $rel = $entry.Replace('/',[IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path -LiteralPath (Join-Path $extract $rel) -PathType Leaf)) {
            throw ('Payload file is missing: ' + $entry)
        }
    }
    # Backup all originals before changing any project file.
    foreach ($entry in $files) {
        $rel = $entry.Replace('/',[IO.Path]::DirectorySeparatorChar)
        $target = Join-Path $projectRoot $rel
        if (Test-Path -LiteralPath $target -PathType Leaf) {
            $dest = Join-Path $backup $rel
            New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force | Out-Null
            Copy-Item -LiteralPath $target -Destination $dest -Force
        }
    }
    $written = New-Object 'System.Collections.Generic.List[string]'
    try {
        foreach ($entry in $files) {
            $rel = $entry.Replace('/',[IO.Path]::DirectorySeparatorChar)
            $target = Join-Path $projectRoot $rel
            New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
            Copy-Item -LiteralPath (Join-Path $extract $rel) -Destination $target -Force
            $written.Add($rel)
        }
    } catch {
        foreach ($rel in $written) {
            $target = Join-Path $projectRoot $rel
            $original = Join-Path $backup $rel
            if (Test-Path -LiteralPath $original -PathType Leaf) {
                Copy-Item -LiteralPath $original -Destination $target -Force
            } else {
                Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
            }
        }
        throw
    }
    Write-Host ''
    Write-Host 'SUCCESS: StockFlow Roles & Trading Point Permissions installed.' -ForegroundColor Green
    Write-Host 'Director: create managers; admin edit/deactivate other employees.'
    Write-Host 'Trading-point manager: create/edit/deactivate sellers in assigned point.'
    Write-Host 'Seller: create sales only in own point; server derives seller ID.'
    Write-Host 'Sales, inventory, trading points and dashboard are scoped by role/point.'
    Write-Host 'Profile and the existing theme styling were preserved.'
    Write-Host ('Backup: ' + $backup) -ForegroundColor Yellow
    Write-Host 'NEXT: restart app, Ctrl+Shift+B in Visual Studio, then sign in again to refresh your cookie.' -ForegroundColor Cyan
    Write-Host 'Open /Employees as Director, create a TradingPointManager for an existing point.' -ForegroundColor Cyan
} finally {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
}
